import { MeshBasicNodeMaterial, PlaneGeometry, BufferGeometry, Mesh, Group, LineSegments, LineBasicMaterial, Color, LineLoop, Line, BufferAttribute } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, length, abs, min, mod } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // ===== PANEL BACKGROUND =====
  const panelW = 3.2;
  const panelH = 2.2;

  const panelGeo = new THREE.PlaneGeometry(panelW, panelH);
  disposables.push(panelGeo);

  // TSL shader: radial gradient + grid pattern
  const uvNode = uv();

  // Compute distance from center for radial gradient
  const localX = uvNode.x.mul(panelW).sub(panelW / 2);
  const localY = uvNode.y.mul(panelH).sub(panelH / 2);
  const distFromCenter = length(vec3(localX, localY, 0));
  const maxDist = Math.sqrt((panelW / 2) ** 2 + (panelH / 2) ** 2);
  const gradT = distFromCenter.div(maxDist).min(1);

  // Gradient from #14141a (center) to #0b0b10 (edges)
  const gradCol0 = new Color('#14141a');
  const gradCol1 = new Color('#0b0b10');
  const gradColor = mix(
    vec3(gradCol0.r, gradCol0.g, gradCol0.b),
    vec3(gradCol1.r, gradCol1.g, gradCol1.b),
    gradT
  );

  // Grid overlay (0.25-unit pitch, #e8ecf2 at 6% opacity)
  const gridPitch = 0.25;
  const gridUV = mod(uvNode.mul(1 / gridPitch), 1);
  const gridDist = min(abs(gridUV.x.sub(0.5)), abs(gridUV.y.sub(0.5)));
  const gridLine = smoothstep(0.015, 0.005, gridDist).mul(0.06);

  const gridCol = new Color('#e8ecf2');
  const gridOverlay = vec3(gridCol.r, gridCol.g, gridCol.b).mul(gridLine);

  const panelColor = mix(gradColor, gradColor.add(gridOverlay), gridLine);

  const panelMat = new MeshBasicNodeMaterial({
    colorNode: panelColor,
    side: THREE.DoubleSide,
  });
  disposables.push(panelMat);

  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  group.add(panelMesh);

  // ===== GHOST PREVIEW (left side) =====
  const ghostGroup = createGhostPreview(THREE, disposables);
  ghostGroup.position.set(-0.75, 0.1, 0.01);
  group.add(ghostGroup);

  // Ghost breathing animation: opacity 0.24 -> 0.34 over 2400ms
  ghostGroup.userData.opacityValue = 0.24;
  const breatheTl = gsap.to(ghostGroup.userData, {
    opacityValue: 0.34,
    duration: 2.4,
    repeat: -1,
    yoyo: true,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    onUpdate() {
      ghostGroup.traverse((child) => {
        if (child.material && child.material.transparent !== undefined) {
          child.material.opacity = ghostGroup.userData.opacityValue;
        }
      });
    },
  });
  timelines.push(breatheTl);

  // ===== TEXT CONTENT =====
  const textItems = config.textContent || config.intent?.visualSpec?.textContent || [];

  let headlineText = 'Your ledger is empty.';
  let bodyText = 'Commissioned pieces and saved references will appear here once you begin.';
  let ctaText = 'BROWSE THE COLLECTION';

  textItems.forEach((item) => {
    if (item.role === 'headline') headlineText = item.text;
    if (item.role === 'body') bodyText = item.text;
    if (item.role === 'cta') ctaText = item.text;
  });

  // Headline (34px, 600 weight, Lora)
  const headlineMesh = ctx.fontAtlas.createText(headlineText, {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -0.34,
  });
  headlineMesh.position.set(0.35, 0.38, 0.01);
  group.add(headlineMesh);

  // Body (13px, 400 weight, JetBrains Mono)
  const bodyMesh = ctx.fontAtlas.createText(bodyText, {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    maxWidthPx: 320,
  });
  bodyMesh.position.set(0.35, -0.08, 0.01);
  group.add(bodyMesh);

  // ===== CTA BUTTON =====
  const ctaButton = createCTAButton(THREE, ctx, ctaText, timelines, disposables);
  ctaButton.position.set(0.35, -0.82, 0.01);
  group.add(ctaButton);

  // ===== MOUNT ANIMATION (fade-up) =====
  gsap.fromTo(
    group,
    { opacity: 0, y: 0.2 },
    {
      opacity: 1,
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }
  );

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => d.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}

function createGhostPreview(THREE, disposables) {
  const group = new THREE.Group();

  const cardW = 1.1;
  const cardH = 1.4;
  const ghostCol = new THREE.Color('#e8ecf2');

  // Wireframe card outline (rectangle)
  const outlinePos = new Float32Array([
    -cardW / 2,
    cardH / 2,
    0,
    cardW / 2,
    cardH / 2,
    0,
    cardW / 2,
    cardH / 2,
    0,
    cardW / 2,
    -cardH / 2,
    0,
    cardW / 2,
    -cardH / 2,
    0,
    -cardW / 2,
    -cardH / 2,
    0,
    -cardW / 2,
    -cardH / 2,
    0,
    -cardW / 2,
    cardH / 2,
    0,
  ]);

  const outlineGeo = new THREE.BufferGeometry();
  outlineGeo.setAttribute('position', new THREE.BufferAttribute(outlinePos, 3));
  disposables.push(outlineGeo);

  const outlineMat = new LineBasicMaterial({
    color: ghostCol,
    opacity: 0.3,
    transparent: true,
  });
  disposables.push(outlineMat);

  const outline = new LineSegments(outlineGeo, outlineMat);
  group.add(outline);

  // Ghost dial circle (0.55 diameter = 0.275 radius)
  const dialR = 0.275;
  const dialSegs = 32;
  const dialPos = new Float32Array((dialSegs + 1) * 3);
  for (let i = 0; i <= dialSegs; i++) {
    const angle = (i / dialSegs) * Math.PI * 2;
    dialPos[i * 3] = Math.cos(angle) * dialR;
    dialPos[i * 3 + 1] = Math.sin(angle) * dialR;
    dialPos[i * 3 + 2] = 0;
  }

  const dialGeo = new THREE.BufferGeometry();
  dialGeo.setAttribute('position', new THREE.BufferAttribute(dialPos, 3));
  disposables.push(dialGeo);

  const dialMat = new LineBasicMaterial({
    color: ghostCol,
    opacity: 0.3,
    transparent: true,
  });
  disposables.push(dialMat);

  const dial = new LineLoop(dialGeo, dialMat);
  dial.position.y = 0.15;
  group.add(dial);

  // Ghost text bars (0.7w x 0.06h, 22% opacity)
  for (let i = 0; i < 2; i++) {
    const y = 0.0 - i * 0.15;
    const barW = 0.7;

    const barPos = new Float32Array([-barW / 2, y, 0, barW / 2, y, 0]);

    const barGeo = new THREE.BufferGeometry();
    barGeo.setAttribute('position', new THREE.BufferAttribute(barPos, 3));
    disposables.push(barGeo);

    const barMat = new LineBasicMaterial({
      color: ghostCol,
      opacity: 0.22,
      transparent: true,
      linewidth: 2,
    });
    disposables.push(barMat);

    const bar = new Line(barGeo, barMat);
    group.add(bar);
  }

  return group;
}

function createCTAButton(THREE, ctx, text, timelines, disposables) {
  const group = new THREE.Group();

  const btnW = 1.5;
  const btnH = 0.36;

  // Button background with vertical gradient (#ff4450 -> #c1121f)
  const btnGeo = new PlaneGeometry(btnW, btnH);
  disposables.push(btnGeo);

  const uvNode = uv();
  const c0 = new Color('#ff4450');
  const c1 = new Color('#c1121f');

  const gradColor = mix(
    vec3(c0.r, c0.g, c0.b),
    vec3(c1.r, c1.g, c1.b),
    uvNode.y
  );

  const btnMat = new MeshBasicNodeMaterial({
    colorNode: gradColor,
    side: THREE.DoubleSide,
  });
  disposables.push(btnMat);

  const btnMesh = new Mesh(btnGeo, btnMat);
  group.add(btnMesh);

  // Button label (ink color, 13px, 700 weight, 0.08em letter spacing)
  const labelMesh = ctx.fontAtlas.createText(text, {
    fontSize: 13,
    color: '#16161d',
    align: 'center',
    letterSpacingPx: 1.04,
  });
  labelMesh.position.z = 0.01;
  group.add(labelMesh);

  // Press animation (scale 1.0 -> 0.97 over 120ms)
  group.userData.handlers = {
    pointerdown: () => {
      const pressTl = gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(pressTl);
    },
    pointerup: () => {
      const releaseTl = gsap.to(group.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      timelines.push(releaseTl);
    },
    click: () => {
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  return group;
}
